INTRO = "Now it is finally Paquita's own turn at the tarot table with María Rosa. With the Goya Awards right around the corner, Paquita wants to know only one thing: whether Mariona will take home Best New Actress. Let's listen in Spanish first."
STORY = [('paquita', 'Venga, y ahora lo que es importante. ¿Hay Goya o no hay Goya?', "Come on, and now for what matters. Is there a Goya or isn't there?", [(180, 'Venga, y ahora lo que es importante'), (181, '¿Hay Goya o no hay Goya?')], ''), ('mariarosa', 'Veamos. Te veo muy ilusionada.', "Let's see. I can tell you're very excited.", [(181, 'Veamos. Te veo muy ilusionada')], ''), ('paquita', 'Pues claro. Mariona está nominada al Goya a Mejor Actriz Revelación.', 'Of course. Mariona is nominated for the Goya for Best New Actress.', [(182, 'Pues claro'), (183, 'Mariona está nominada al Goya a Mejor Actriz Revelación')], ''), ('paquita', 'Estoy muy emocionada. Puede ser un momento muy importante para nuestra oficina.', "I'm thrilled. It could be a very important moment for our office.", [(188, 'Estoy muy emocionada'), (189, 'Puede ser un momento muy importante para nuestra oficina')], ''), ('paquita', 'Otro Goya, después del de Macarena. Pues ahora el de Mariona.', "Another Goya, after Macarena's. Now Mariona's.", [(190, 'Otro Goya, después del de'), (191, 'Macarena. Pues ahora el de Mariona')], ''), ('mariarosa', 'Vamos a verlo. Venga, corta, mi vida.', "Let's see. Go ahead and cut the deck, darling.", [(192, 'Vamos a verlo'), (193, 'Venga, corta, mi vida')], ''), ('paquita', 'Corto, a ver. ¿Qué montón me das, este o este?', "I'm cutting, let's see. Which pile do you give me, this one or this one?", [(194, 'Corto, a ver'), (195, '¿Qué montón me das, este o este?')], ''), ('mariarosa', 'Este montón. Muy bien, vamos a ver las energías. ¡La carta del sol, Paquita!', "This pile. Very good, let's check the energy. The Sun card, Paquita!", [(195, 'Este montón'), (196, 'Muy bien, vamos a ver las energías'), (197, 'La carta del sol, Paquita')], ''), ('mariarosa', 'Empezamos bien. ¡La carta de la estrella! La carta de los artistas.', "We're off to a good start. The Star card! The card of artists.", [(198, 'Empezamos bien'), (199, 'La carta de la estrella'), (200, 'La carta de los artistas')], ''), ('mariarosa', '¡La estrella es el éxito, Paquita! Es el Goya. Te lo mereces.', "The Star is success, Paquita! It's the Goya. You deserve it.", [(201, 'La estrella es el éxito, Paquita. Es el Goya'), (202, 'Te lo mereces')], ''), ('paquita', '¡Hay Goya! ¡Ay, por favor! ¿De verdad?', "There's a Goya! Oh, please! Really?", [(203, '¡Hay Goya! ¡Ay, por favor!'), (204, '¿De verdad?')], ''), ('mariarosa', 'Te prometo que hay Goya. Las cartas no mienten.', "I promise you there's a Goya. The cards don't lie.", [(205, 'Te prometo que hay Goya. Las cartas no mienten')], ''), ('paquita', 'Yo llevaba unos días que lo veía venir, ¿sabes? No me lo creo.', "For a few days now I could feel it coming, you know? I can't believe it.", [(207, 'Yo llevaba unos días que lo veía venir, ¿sabes?'), (209, 'No me lo creo')], ''), ('paquita', 'Mira, la niña. La hemos invocado. A ver qué dice.', "Look, it's the girl calling. We summoned her. Let's see what she says.", [(212, 'Mira, la niña'), (213, 'La hemos invocado'), (214, 'A ver qué dice')], '')]
